/**
 * SDF Sphere-Sphere collision detection.
 *
 * Simple distance check between sphere centers. O(1) complexity.
 * Uses capsuleInfo.radius as sphere radius.
 *
 * @param {Object} bodyA - First body with transformer, capsuleInfo
 * @param {Object} bodyB - Second body with transformer, capsuleInfo
 * @param {CollisionResult} result - Output object (reused to avoid allocations)
 * @returns {boolean} True if collision detected
 */
export function sphereSphereCollide(bodyA: any, bodyB: any, result: CollisionResult): boolean;
/**
 * SDF Capsule-Capsule collision detection.
 *
 * Finds closest points between capsule segments and tests radii. O(1) complexity.
 * Uses capsuleInfo.segment for the capsule line segment and capsuleInfo.radius.
 *
 * @param {Object} bodyA - First body with transformer, capsuleInfo
 * @param {Object} bodyB - Second body with transformer, capsuleInfo
 * @param {CollisionResult} result - Output object (reused to avoid allocations)
 * @returns {boolean} True if collision detected
 */
export function capsuleCapsuleCollide(bodyA: any, bodyB: any, result: CollisionResult): boolean;
/**
 * BVH-to-Box collision detection (fast mode).
 *
 * Uses A's BVH shapecast against B's transformed bounding box.
 * Good balance of speed and accuracy for most convex shapes.
 *
 * Handles mixed SDF/BVH pairs: if one body has no BVH (capsule-only),
 * uses capsuleInfo to compute bounding box instead.
 *
 * @param {Object} bodyA - First body with bvh, transformer
 * @param {Object} bodyB - Second body with bvh, transformer
 * @param {BvhCollisionResult} result - Output object (reused to avoid allocations)
 * @returns {boolean} True if collision detected
 */
export function bvhBoxCollide(bodyA: any, bodyB: any, result: BvhCollisionResult): boolean;
/**
 * Fast BVH-to-BVH collision detection using intersectsGeometry + AABB approximation.
 *
 * Uses three-mesh-bvh's intersectsGeometry for fast boolean detection (O(log n × log m)),
 * then approximates penetration depth and contact normal from AABB overlap.
 *
 * This is the default FULL mode - fast enough for real-time physics with good accuracy.
 *
 * @param {Object} bodyA - First body with bvh, transformer
 * @param {Object} bodyB - Second body with bvh, transformer
 * @param {BvhCollisionResult} result - Output object (reused to avoid allocations)
 * @returns {boolean} True if collision detected
 */
export function bvhBvhCollideFull(bodyA: any, bodyB: any, result: BvhCollisionResult): boolean;
/**
 * Precise BVH-to-BVH collision detection using bvhcast with triangle tests.
 *
 * Uses bvhcast for efficient nested BVH traversal with triangle-triangle distance tests.
 * More accurate contact points but slower than bvhBvhCollideFull.
 *
 * Use FULL_PRECISE collision type when exact contact normal/point is critical.
 *
 * @param {Object} bodyA - First body with bvh, transformer
 * @param {Object} bodyB - Second body with bvh, transformer
 * @param {BvhCollisionResult} result - Output object (reused to avoid allocations)
 * @returns {boolean} True if collision detected
 */
export function bvhBvhCollidePrecise(bodyA: any, bodyB: any, result: BvhCollisionResult): boolean;
/**
 * Main collision function that dispatches to appropriate method based on body settings.
 *
 * Selects collision algorithm based on BodyCollisionType:
 * - SPHERE: sphereSphereCollide (O(1) SDF)
 * - CAPSULE: capsuleCapsuleCollide (O(1) SDF)
 * - BOX: bvhBoxCollide (O(log n) BVH)
 * - FULL: bvhBvhCollideFull (O(log n × log m) fast BVH via intersectsGeometry)
 * - FULL_PRECISE: bvhBvhCollidePrecise (O(n log n) precise BVH with triangle tests)
 *
 * When bodies have different collision types, uses the more accurate (higher) type.
 *
 * @param {Object} bodyA - First dynamic body
 * @param {Object} bodyB - Second dynamic body
 * @param {Object} sDynamicA - SharedArrayBuffer view for body A (has collisionType)
 * @param {Object} sDynamicB - SharedArrayBuffer view for body B (has collisionType)
 * @param {CollisionResult} result - Output object
 * @returns {boolean} True if collision detected
 */
export function bvhBvhCollide(bodyA: any, bodyB: any, sDynamicA: any, sDynamicB: any, result: CollisionResult): boolean;
/**
 * Get collected multi-contacts.
 * @returns {{count: number, contacts: Array}} Multi-contact result
 */
export function getMultiContacts(): {
    count: number;
    contacts: any[];
};
/**
 * Multi-point collision detection dispatcher.
 *
 * Dispatches to appropriate collision method and collects multiple contacts
 * for RAPIER-style manifolds. Returns up to 4 diverse contact points.
 *
 * For SDF types (SPHERE, CAPSULE), only 1 contact is generated.
 * For BVH types (BOX, FULL, FULL_PRECISE), multiple contacts are collected.
 *
 * @param {Object} bodyA - First dynamic body
 * @param {Object} bodyB - Second dynamic body
 * @param {Object} sDynamicA - SharedArrayBuffer view for body A
 * @param {Object} sDynamicB - SharedArrayBuffer view for body B
 * @param {CollisionResult} result - Primary result (deepest contact)
 * @returns {boolean} True if collision detected
 */
export function bvhBvhCollideMultiPoint(bodyA: any, bodyB: any, sDynamicA: any, sDynamicB: any, result: CollisionResult): boolean;
/**
 * Result object for collision detection
 */
export type CollisionResult = {
    /**
     * - Overlap depth
     */
    penetration: number;
    /**
     * - Contact normal (A to B)
     */
    normal: THREE.Vector3;
    /**
     * - Point of contact
     */
    contactPoint: THREE.Vector3;
};
/**
 * Multi-point contact result for RAPIER-style manifolds
 */
export type MultiContactResult = {
    /**
     * - Number of contacts found
     */
    count: number;
    contacts: Array<{
        penetration: number;
        normal: THREE.Vector3;
        point: THREE.Vector3;
    }>;
};
